import { Alert, AlertTitle, AlertDescription } from './components/ui/alert';
import { IconChevronDown, IconChevronRight, IconInfoCircle, IconSearch, IconFilter, IconArrowsSort, IconPencil, IconSpeakerphone, IconCheck, IconPlayerPause, IconPlayerPlay, IconShieldOff } from '@tabler/icons-react';
import { resourceConflictIds } from './queueResourceConflicts';
type Plan=QueuePublishedSelectionPlanV3|QueuePublishedSelectionPlanV4;
type PlanAction='amend'|'call'|'start'|'complete'|'cancelProtection';
export type NamedChildTarget={child:QueueChildExecutionV3;label:string;courtId:string;isCourt:boolean};
type Props<P extends Plan>={plans:P[];timeZone?:string;drafts?:SavedQueueDraft[];draftActions?:SavedDraftTableActions;draftServiceNames?:Readonly<Record<string,string>>;busy:boolean;onPlanAction:(plan:P,action:PlanAction)=>void;onChildAction:(plan:P,target:NamedChildTarget,action:'complete'|'interrupt'|'retry')=>void;receivedAt?:number;receivedAtById?:Record<string,number>;readFailed?:boolean;headerActions?:ReactNode;toolbarActions?:ReactNode};
const sortOptions=[{value:'fifo',label:'Oldest First'},{value:'newest',label:'Newest First'},{value:'customer',label:'Customer'},{value:'ticket',label:'Ticket'}];
const readOnlyDraftActions:SavedDraftTableActions={busy:true,onEdit(){},onPublish(){},onDelete(){}};
const clock=(value:string)=>new Date(value).toLocaleTimeString('en-PH',{hour:'2-digit',minute:'2-digit',second:'2-digit'});
export function NamedQueueOperations<P extends Plan>(props:Props<P>){
 const [search,setSearch]=useState(''),[status,setStatus]=useState('all'),[sort,setSort]=useState('fifo'),[page,setPage]=useState(0),[open,setOpen]=useState<string[]>([]);
 const tableId=useId();const tick=useRequestClock();
 const resourceConflicts=useMemo(()=>resourceConflictIds(props.plans),[props.plans]);
 const nowFor=(plan:P)=>{const receipt=props.receivedAtById?.[plan.id]??props.receivedAt;return receipt?Date.parse(plan.observedAt)+(tick?Math.max(0,tick-receipt):0):Number.NaN;};
 const rows=useMemo(()=>serviceRequestRows(props.plans,props.drafts||[],search,status,sort,props.draftServiceNames),[props.plans,props.drafts,props.draftServiceNames,search,status,sort]);
 const statusOptions=[{value:'all',label:'All Statuses'},...[...new Set(['draft','waiting','in_service',...props.plans.map(plan=>plan.state)])].map(value=>({value,label:value.replaceAll('_',' ').replace(/\b\w/g,letter=>letter.toUpperCase())}))];
 const {pages,currentPage,visibleRows}=serviceRequestPage(rows,page);
 return <section className="named-queue-operations request-data-table" aria-label="Service request list"><div className="ops-list-heading request-card-heading"><div><h2 className="ops-heading">Service requests</h2><p className="ops-muted">Select services, resources and nested extras. Each selection has an explicit outcome.</p></div>{props.headerActions?<div className="request-card-actions">{props.headerActions}</div>:null}</div>
 <div className="request-table-surface"><div className="request-filter-surface"><div className="request-table-toolbar">
 <div className="request-search-field"><IconSearch aria-hidden="true"/><Input aria-label="Search loaded service requests" placeholder="Search requests…" value={search} onChange={event=>{setSearch(event.target.value);setPage(0);}}/></div>
 <div className="request-filter-controls">
 <Select items={statusOptions} value={status} onValueChange={value=>{if(value!==null){setStatus(value);setPage(0);}}}>
 <SelectTrigger className="request-select-control" aria-label="Filter requests by status" title="Filter requests by status"><IconFilter aria-hidden="true" data-icon="inline-start"/><SelectValue/></SelectTrigger>
 <SelectContent align="end" alignItemWithTrigger={false}><SelectGroup>{statusOptions.map(item=><SelectItem key={item.value} value={item.value}>{item.label}</SelectItem>)}</SelectGroup></SelectContent>
 </Select>
 <Select items={sortOptions} value={sort} onValueChange={value=>{if(value!==null){setSort(value);setPage(0);}}}>
 <SelectTrigger className="request-select-control" aria-label="Sort requests" title="Sort requests by date, customer, or ticket"><IconArrowsSort aria-hidden="true" data-icon="inline-start"/><SelectValue/></SelectTrigger>
 <SelectContent align="end" alignItemWithTrigger={false}><SelectGroup>{sortOptions.map(item=><SelectItem key={item.value} value={item.value}>{item.label}</SelectItem>)}</SelectGroup></SelectContent>
 </Select>{props.toolbarActions?<div className="request-toolbar-actions">{props.toolbarActions}</div>:null}</div></div></div>
 {props.receivedAt&&tick-props.receivedAt>60000?<p role="status">State update is over a minute old. Timing continues from the last server observation; current outcomes need refresh.</p>:null}
 {props.readFailed?<p role="status">Updates unavailable. Showing the last received state; refresh before acting.</p>:null}
 <div className="request-table-body-surface"><Table aria-label="Service request transactions"><TableHeader><TableRow><TableHead>Progress</TableHead><TableHead>Request</TableHead><TableHead>Status</TableHead><TableHead>Services</TableHead><TableHead>Last updated</TableHead><TableHead className="request-actions-column">Actions</TableHead></TableRow></TableHeader><TableBody>
 {visibleRows.map(row=>{if(row.kind==='draft')return <SavedRequestDraftRow key={row.key} draft={row.draft} actions={props.draftActions||readOnlyDraftActions} expanded={open.includes(row.key)} detailId={`${tableId}-${row.key}`} onToggle={()=>setOpen(value=>value.includes(row.key)?value.filter(id=>id!==row.key):[...value,row.key])} serviceNames={props.draftServiceNames||{}}/>;const plan=row.plan;const expanded=open.includes(plan.id),detailId=`${tableId}-${plan.id}`,now=nowFor(plan),counts=requestOutcomeCounts(plan,now),resourceConflict=resourceConflicts.has(plan.id),resourceConflictTone=plan.resourceWait?.code==='RESOURCE_CAPACITY_UNAVAILABLE'?'error':'warning';return <Fragment key={plan.id}><TableRow className={resourceConflict?`request-resource-conflict request-resource-conflict--${resourceConflictTone}`:undefined}><TableCell data-label="Progress"><OverallRequestProgress plan={plan} now={now} counts={counts} timeZone={props.timeZone}/></TableCell><TableCell data-label="Request"><div className="request-table-identity"><Button variant="ghost" size="icon" aria-label={`${expanded?'Collapse':'Expand'} request ${plan.ticketNumber}`} aria-expanded={expanded} aria-controls={detailId} onClick={()=>setOpen(value=>value.includes(plan.id)?value.filter(id=>id!==plan.id):[...value,plan.id])}>{expanded?<IconChevronDown/>:<IconChevronRight/>}</Button><div><strong>{plan.ticketNumber}</strong><p>{plan.customer.name||'Customer'}</p></div></div></TableCell><TableCell data-label="Status"><RequestStatusBadge state={plan.state}/>{plan.state==='waiting'?<ServiceHoursNotice eligibility={plan.serviceHoursEligibility}/>:null}{counts.overdue?<Badge variant="warning">{counts.overdue} OVERDUE</Badge>:null}</TableCell><TableCell data-label="Services"><p>{plan.serviceSelections.length} service(s)</p></TableCell><TableCell data-label="Last updated"><p>{Number.isFinite(Date.parse(plan.observedAt))?clock(plan.observedAt):'unavailable'}</p></TableCell><TableCell data-label="Actions"><RequestActions {...props} plan={plan}/></TableCell></TableRow><TableRow hidden={!expanded} className="request-detail-row"><TableCell colSpan={6}><div id={detailId}><NamedRequestCard {...props} plan={plan} now={now}/></div></TableCell></TableRow></Fragment>;})}
 {!rows.length?<TableRow><TableCell colSpan={6}>No matching loaded requests.</TableCell></TableRow>:null}
 </TableBody></Table></div><div className="request-table-pagination"><span>{rows.length?currentPage*10+1:0}–{Math.min((currentPage+1)*10,rows.length)} of {rows.length} loaded requests</span><Button variant="outline" disabled={currentPage===0} onClick={()=>setPage(currentPage-1)}>Previous</Button><span>Page {currentPage+1} of {pages}</span><Button variant="outline" disabled={currentPage+1>=pages} onClick={()=>setPage(currentPage+1)}>Next</Button></div></div></section>;
}
function RequestActions<P extends Plan>({plan,busy,onPlanAction,onChildAction}:Omit<Props<P>,'plans'>&{plan:P}){const active=plan.serviceSelections.flatMap(service=>service.resources.map(resource=>({child:resource.execution,label:resource.resourceMemberName||service.serviceName,courtId:resource.resourceSelectionId,isCourt:true}))).find(item=>item.child?.isCurrent&&item.child.state==='in_service');const activeTarget=active?.child?{...active,child:active.child}:null;const hasActiveChild=plan.serviceSelections.some(service=>service.resources.some(resource=>resource.execution?.isCurrent&&resource.execution.state==='in_service'||resource.extras.some(extra=>namedExtraExecutions(extra).some(member=>member.execution?.isCurrent&&member.execution.state==='in_service'))));return <TooltipProvider><div className="queue-action-cell"><div className="request-row-actions">{(['amend','call','start','cancelProtection'] as const).filter(action=>plan.allowedActions.includes(action)).map(action=>{
 const label=action==='amend'?'Amend request':action==='call'?'Call request':action==='cancelProtection'?'Cancel protection':'Start service';
 const icon=action==='amend'?<IconPencil/>:action==='call'?<IconSpeakerphone/>:action==='cancelProtection'?<IconShieldOff/>:<IconPlayerPlay/>;
 return <RequestActionButton key={action} label={label} ticket={plan.ticketNumber} intent={action==='amend'?'neutral':action==='cancelProtection'?'interrupt':'info'} disabled={busy||!plan.capabilities.execution||(action==='call'&&!serviceHoursCallAllowed(plan.serviceHoursEligibility))} onClick={()=>onPlanAction(plan,action)}>{icon}</RequestActionButton>;
 })}{hasActiveChild?<RequestActionButton label="Complete" ticket={plan.ticketNumber} intent="success" disabled={busy||!plan.capabilities.childOutcomes} onClick={()=>onPlanAction(plan,'complete')}><IconCheck/></RequestActionButton>:null}{activeTarget?<RequestActionButton label="Interrupt" ticket={plan.ticketNumber} intent="interrupt" disabled={busy||!plan.capabilities.childOutcomes} onClick={()=>onChildAction(plan,activeTarget,'interrupt')}><IconPlayerPause/></RequestActionButton>:null}</div></div></TooltipProvider>;}
function RequestActionButton({label,ticket,intent,disabled,onClick,children}:{label:string;ticket:string;intent:'neutral'|'info'|'success'|'interrupt';disabled:boolean;onClick:()=>void;children:ReactNode}){
 return <Tooltip><TooltipTrigger render={<Button variant="ghost" size="icon" className="request-row-action" data-intent={intent} disabled={disabled} aria-label={`${label} for ${ticket}`} onClick={onClick}/>}>{children}</TooltipTrigger><TooltipContent>{label}</TooltipContent></Tooltip>;
}

 function OverallRequestProgress<P extends Plan>({plan,now,counts,timeZone}:{plan:P;now:number;counts:{completed:number;total:number};timeZone?:string}){const expected=requestExpectedEnd(plan,now,timeZone);const members=plan.allocationGroups.flatMap(group=>group.members).filter(member=>member.startedAt&&member.expectedEndAt);let percent=counts.total?counts.completed/counts.total*100:0;if(members.length){const start=Math.min(...members.map(member=>Date.parse(member.startedAt!))),end=Math.max(...members.map(member=>Date.parse(member.expectedEndAt!)));if(Number.isFinite(now)&&Number.isFinite(start)&&end>start)percent=((now-start)/(end-start))*100;}percent=Math.max(0,Math.min(100,percent));const rounded=Math.round(percent),band=percent<=25?'blue':percent<=50?'green':percent<=75?'orange':'red',visibleProgress=`${percent}%`;return <div className="request-overall-progress" data-progress-band={band}><div className="request-progress-ring" role="progressbar" aria-valuemin={0} aria-valuemax={100} aria-valuenow={rounded} aria-label={`Request completion progress ${rounded}%`} style={{'--progress':visibleProgress} as CSSProperties}><span>{rounded}%</span></div>{expected?<span className="request-end-time" data-overdue={expected.overdue}><time dateTime={expected.iso} aria-label={`${expected.workOnly?'Current active work':'Current service'} expected end ${expected.label}`}>{expected.workOnly?'Current work ends ':''}{expected.label}</time><small>{expected.countdown}</small></span>:plan.state==='in_service'?<span className="request-end-time request-metadata">Timing unavailable</span>:null}</div>;}
function NamedRequestCard<P extends Plan>({plan,busy,onChildAction,now}:Omit<Props<P>,'plans'>&{plan:P;now:number}){
 const [expanded,setExpanded]=useState<string[]>(()=>initiallyExpandedServices(plan));
 const summaries=publishedServiceSummaries(plan);
 function execution(child:QueueChildExecutionV3|null,label:string,courtId:string,isCourt:boolean,displayLabel=label){
  if(!child)return <p className="request-metadata">No execution attempt recorded.</p>;
  const members=plan.allocationGroups.flatMap(group=>group.members).filter(member=>member.childAttemptId===child.childAttemptId&&child.allocationMemberIds.includes(member.id));
  return <div className="request-execution"><p className="request-execution-state"><RequestStatusBadge state={child.state}/><span className="request-metadata">Attempt {child.attempt}</span></p>{!members.length?<p className="request-metadata">{child.startedAt?'Timing unavailable':'Not started'}</p>:null}{members.map(member=><div key={member.id}><RequestDurationProgress member={member} now={now} label={label} current={child.isCurrent&&child.state==='in_service'}/><p className="request-metadata request-timestamps">{member.units} resource unit(s) · Started {clock(member.startedAt)} · Expected end {clock(member.expectedEndAt)} · {member.releasedAt?`Released ${clock(member.releasedAt)}`:'Still held'}</p></div>)}{child.satisfiedDependencyAttemptIds.length?<p className="request-metadata">Completed extras retained from {child.satisfiedDependencyAttemptIds.length} earlier attempt(s).</p>:null}{child.allowedActions.length?<div className="queue-row">{child.allowedActions.map(action=><Button key={action} className="v:h-auto v:min-h-11 v:max-w-full v:whitespace-normal v:text-left" variant={action==='interrupt'?'outline':'default'} disabled={busy||!plan.capabilities.childOutcomes} onClick={()=>onChildAction(plan,{child,label,courtId,isCourt},action)}><span className="v:min-w-0 v:break-words">{action==='complete'?'Complete':action==='interrupt'?'Interrupt':'Retry'} {displayLabel}</span>{displayLabel!==label?<span className="v:sr-only"> for {label}</span>:null}</Button>)}</div>:null}</div>;
 }
 return <section aria-label={`Details for ${plan.ticketNumber}`}>

  <div className="queue-stack request-review-content">{plan.state==='waiting'?<ServiceHoursNotice eligibility={plan.serviceHoursEligibility} showNeutral/>:null}<p className="request-metadata">Stage {plan.currentStage.ordinal} · <RequestStatusBadge state={plan.currentStage.state}/> · Configuration {plan.workflow.configurationRevision}</p>
 {plan.resourceWait?<Alert variant={plan.resourceWait.code==='RESOURCE_CAPACITY_UNAVAILABLE'?'error':'warning'} className={`request-resource-alert request-resource-alert--${plan.resourceWait.code==='RESOURCE_CAPACITY_UNAVAILABLE'?'error':'warning'}`}><IconInfoCircle aria-hidden="true"/><AlertTitle>Waiting for resources</AlertTitle><AlertDescription>{[plan.resourceWait.parentResourceName||plan.resourceWait.resourceMemberName,plan.resourceWait.serviceName].filter(Boolean).join(' · ')}{plan.resourceWait.serviceName?' — ':''}{plan.resourceWait.message}</AlertDescription></Alert>:null}
  <Accordion multiple keepMounted value={expanded} onValueChange={setExpanded} className="published-service-accordion">
   {plan.serviceSelections.map((service,index)=>{const summary=summaries[index];return <AccordionItem key={service.serviceSelectionId} value={service.serviceSelectionId} className="published-service-item">
    <AccordionTrigger iconPosition="start" headingLevel={4} className="published-service-trigger"><span className="published-service-heading"><span className="published-service-name">{service.serviceName}</span><span className="published-service-summary">{summary.resourceCount} resource{summary.resourceCount===1?'':'s'} · {summary.extraCount} extra{summary.extraCount===1?'':'s'} · {summary.statuses}{service.resources.flatMap(resource=>[resource.execution,...resource.extras.flatMap(extra=>namedExtraExecutions(extra).map(member=>member.execution))]).filter(child=>child?.isCurrent&&child.state==='in_service'&&plan.allocationGroups.flatMap(group=>group.members).some(member=>member.childAttemptId===child.childAttemptId&&child.allocationMemberIds.includes(member.id)&&durationInterval(member,now)?.overdue)).length?' · OVERDUE':''}{summary.actionCount?` · ${summary.actionCount} resource action${summary.actionCount===1?'':'s'} available — expand to manage`:''}</span></span></AccordionTrigger>
    <AccordionContent keepMounted className="published-service-content"><section aria-label={`${service.serviceName} selections for ${plan.ticketNumber}`}><ol className="request-resource-list">{service.resources.map((court,resourceIndex)=><li key={court.resourceSelectionId} className="request-resource"><div className="request-resource-heading"><h5>{court.resourceMemberName||`${service.serviceName} resource ${resourceIndex+1}`}</h5><p className="request-duration">{readableDuration(court.durationMinutes)}</p></div><p className="request-metadata">{court.quantity} resource unit(s){'durationCount' in court?` · ${String(court.durationCount)} × ${String(court.baseMinutes)} minutes = ${court.durationMinutes} minutes total`:''}</p>
     {execution(court.execution,court.resourceMemberName||`${service.serviceName} resource ${resourceIndex+1}`,court.resourceSelectionId,true)}
     {court.extras.length?<ul className="request-extra-list" aria-label={`Required extras for ${court.resourceMemberName}`}>{court.extras.map(extra=><li key={extra.extraSelectionId}><p className="request-extra-label">{extra.serviceName}</p><p className="request-metadata">{extra.quantity} unit(s) · {readableDuration(extra.durationMinutes)}{'durationCount' in extra?` · ${String(extra.durationCount)} × ${String(extra.baseMinutes)} minutes = ${extra.durationMinutes} minutes total`:''}</p>{namedExtraExecutions(extra).map(member=><div className="request-extra-member" key={member.id}>{'namedExtraVersion' in extra&&extra.namedExtraVersion===1?<p className="request-member-name">{member.memberName}</p>:null}{execution(member.execution,`extra ${member.name} for ${court.resourceMemberName||service.serviceName}`,court.resourceSelectionId,false,member.memberName)}</div>)}</li>)}</ul>:<p className="request-metadata">No extras for this resource.</p>}
    </li>)}</ol></section></AccordionContent>
   </AccordionItem>;})}
  </Accordion>
  <div className="request-record-summary"><p className="request-metadata">Quote unavailable · service pricing is not configured.</p><p className="request-metadata">Started resources release through explicit outcomes. Required extras finish before their parent.</p>{plan.reservationGroups.map(group=><p className="request-metadata" key={group.id}>Reservation <RequestStatusBadge state={group.state}/> · {group.members.length} recorded member(s){group.state==='protected'?` · Protection expires ${clock(group.expiresAt)}`:''}</p>)}{plan.allocationGroups.map(group=><p className="request-metadata" key={group.id}>Allocation group: <RequestStatusBadge state={group.resolutionState}/> · {group.members.filter(member=>!member.releasedAt).length} member(s) still held · {group.members.filter(member=>Boolean(member.releasedAt)).length} explicitly released</p>)}</div>
  </div>
 </section>;
}
